sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float beat;
uniform float maxCell;
uniform float curve;
uniform float snap;
uniform float levels;
uniform float opacity;
uniform float decay;
uniform float beats;
uniform float offset;
uniform float bpm;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float e = pow(saturate(beat), curve);
    float cellF = mix(1.0, maxCell, e);
    float cell = mix(cellF, floor(cellF + 0.5), snap);
    float4 r = c;
    if (cell > 1.5) {
        r = tex((floor(coord / cell) + 0.5) * cell);
        if (levels >= 2.0) {
            float3 s = unp(r);
            s = floor(s * (levels - 1.0) + 0.5) / (levels - 1.0);
            r = float4(s * r.a, r.a);
        }
    }
    return fin(c, r, opacity);
}
